import { readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const sourcePath = join(root, "internal", "controlplane", "ui", "product.css");
const outputPath = join(root, "internal", "hosted", "app", "src", "product-css.generated.ts");
const source = await readFile(sourcePath, "utf8");
const output =
  "// Generated by scripts/generate-hosted-design.mjs. Do not edit.\n" +
  "// Source of truth: internal/controlplane/ui/product.css\n" +
  `export const PRODUCT_CSS = String.raw\`${source}\`;\n`;

if (process.argv.includes("--check")) {
  const current = await readFile(outputPath, "utf8").catch(() => "");
  if (current !== output) {
    console.error("hosted design CSS is stale; run pnpm -C internal/hosted/app design:generate");
    process.exitCode = 1;
  }
} else {
  await writeFile(outputPath, output);
}
